22: const handleResponse = async (response: Response) => {
23:   const contentType = response.headers.get('content-type');
24:   const isJson = contentType && contentType.includes('application/json');
25:   
26:   if (!response.ok) {
27:     const data = isJson ? await response.json() : await response.text();
28:     if (isJson && (data as FHIRError).issue) {
29:       const fhirError = data as FHIRError;
30:       throw new Error(
31:         fhirError.issue
32:           .map(issue => `${issue.severity}: ${issue.diagnostics}`)
33:           .join('. ')
34:       );
35:     }
36:     throw new Error(handleFHIRError({ status: response.status, message: data }));
37:   }
38: 
39:   const data = isJson ? await response.json() : await response.text();
40:   return data;
41: };
